package com.bank.postmortem;

import com.bank.postmortem.model.IncidentRecord;
import com.bank.postmortem.service.PostmortemService;
import java.util.List;
import java.util.logging.*;

// Runnable demo: grade incident write-ups by evidence, impact, and prevention.
public class PostmortemDemo {
    private static final Logger log = Logger.getLogger("Postmortem");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        PostmortemService service = new PostmortemService(log);

        // Junior-style: chronological, no evidence, no quantified impact, no prevention.
        IncidentRecord junior = new IncidentRecord(
            "Settlement service was down",
            List.of(),              // no evidence named
            0,                      // impact not quantified
            "something went wrong",
            0, 0,                   // no before/after metric
            null);                  // no prevention
        service.publish(junior);

        // Senior-style: evidence + quantified impact + root cause + metric + prevention.
        IncidentRecord senior = new IncidentRecord(
            "Trade-settlement service down 12 min during market close",
            List.of("latency metrics", "distributed traces", "JVM thread dump"),
            2000,                   // ~2000 trades blocked (quantified impact)
            "One slow FX dependency starved the shared thread pool (thread dump: 40 threads WAITING)",
            40, 10,                 // MTTR before 40 min, after 10 min
            "Added bulkhead isolation per dependency + alert on pool saturation");
        service.publish(senior);
    }
}
