package com.bank.postmortem.model;

import java.util.List;

// A structured incident record: STAR plus evidence, impact, and prevention.
public class IncidentRecord {
    private final String situation;
    private final List<String> evidence;   // logs, metrics, traces, dumps
    private final int impactUnits;         // quantified business impact
    private final String rootCause;
    private final int mttrBefore;          // result metric before
    private final int mttrAfter;           // result metric after
    private final String prevention;       // corrective action, null if none

    public IncidentRecord(String situation, List<String> evidence, int impactUnits,
                          String rootCause, int mttrBefore, int mttrAfter, String prevention) {
        this.situation = situation;
        this.evidence = evidence;
        this.impactUnits = impactUnits;
        this.rootCause = rootCause;
        this.mttrBefore = mttrBefore;
        this.mttrAfter = mttrAfter;
        this.prevention = prevention;
    }

    public String getSituation() { return situation; }
    public List<String> getEvidence() { return evidence; }
    public int getImpactUnits() { return impactUnits; }
    public String getRootCause() { return rootCause; }
    public int getMttrBefore() { return mttrBefore; }
    public int getMttrAfter() { return mttrAfter; }
    public String getPrevention() { return prevention; }

    // Senior-grade = has evidence, quantified impact, and a prevention.
    public boolean isSeniorGrade() {
        return evidence != null && !evidence.isEmpty()
            && impactUnits > 0
            && prevention != null && !prevention.isBlank();
    }
}
