package com.bank.postmortem.service;

import com.bank.postmortem.model.IncidentRecord;
import java.util.logging.*;

// Publishes the postmortem in STAR order and grades it junior vs senior.
public class PostmortemService {
    private final Logger log;

    public PostmortemService(Logger log) { this.log = log; }

    public void publish(IncidentRecord r) {
        if (!r.isSeniorGrade()) {
            log.warning(() -> "JUNIOR retelling: \"" + r.getSituation()
                + "\" — missing evidence, quantified impact, or prevention.");
            return;
        }
        int improvement = r.getMttrBefore() - r.getMttrAfter();
        log.info(() -> "SITUATION: " + r.getSituation()
            + " (impact: ~" + r.getImpactUnits() + " trades blocked)");
        log.info(() -> "ACTION/EVIDENCE: investigated via " + r.getEvidence());
        log.info(() -> "ROOT CAUSE: " + r.getRootCause());
        log.info(() -> "RESULT: MTTR " + r.getMttrBefore() + "min to "
            + r.getMttrAfter() + "min (improved " + improvement + "min)");
        log.info(() -> "PREVENTION: " + r.getPrevention());
    }
}
